local script=debug.getinfo(1,'S').source:sub(2);local dir=script:match('^(.*)[/\\]');package.path=dir..'/?.lua;'..package.path
local b=require('_bootstrap');local a=b.lib('args');local o=a.parse(arg);local path=b.lib('path');local process=b.lib('process');local exe=path.absolute(a.required(o,'exe'));local cwd=path.absolute(o.cwd or o['working-directory']or'omb');local stdout=path.absolute(o.stdout or'omb/log/launcher_backend_stdout.log');local stderr=path.absolute(o.stderr or'omb/log/launcher_backend_stderr.log');local pid=process.spawn(exe,{}, {cwd=cwd,stdout=stdout,stderr=stderr});process.poll_ready(pid,20000,function()return(path.exists(stdout)and path.read(stdout):find('Starting KCP server on',1,true))or(path.exists(stderr)and path.read(stderr):find('Starting KCP server on',1,true))end,'backend KCP');if o['pid-file']then path.write(path.absolute(o['pid-file']),tostring(pid)..'\r\n',true)else print(pid)end
